use std::fs

fn best(pris: Vec<int>) -> int {
    let mut bi = 0
    let mut i = 1
    while i < pris.len() as int {
        if pris[i] > pris[bi] {
            bi = i
        }
        i += 1
    }
    bi
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut names: Vec<string> = []
    let mut pris: Vec<int> = []
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        let n: int = parts.len() as int
        if n == 3 && parts[0] == "add" {
            match parts[2].parse::<int>() {
                Ok(p) => {
                    names.push(parts[1])
                    pris.push(p)
                }
                Err(_) => println("error"),
            }
        } else if n == 1 && parts[0] == "pop" {
            if names.len() == 0 {
                println("empty")
            } else {
                let b = best(pris)
                println(names[b])
                names.remove(b)
                pris.remove(b)
            }
        } else if n == 1 && parts[0] == "peek" {
            if names.len() == 0 {
                println("empty")
            } else {
                let b = best(pris)
                println(names[b])
            }
        } else if n == 1 && parts[0] == "size" {
            println("${names.len()}")
        } else {
            println("error")
        }
    }
    println("left:")
    while names.len() > 0 {
        let b = best(pris)
        println("${names[b]} ${pris[b]}")
        names.remove(b)
        pris.remove(b)
    }
}

